+/**
+ * @brief 验证 MC->TH 在途级联关联状态受保护不被后续并发级联覆盖，并在响应后恢复正常
+ */
+static void test_twin47_cascade_pending_guard_and_recovery(void)
+{
+    s_test_seq = 100U;
+    const minimc_filament_req_t fil_req = { 1U, 0U, 50U };
+    clear_usart1_capture();
+    /* 1. 发起第1条 MC->TH 级联 (seq=101, cmd=0x19)，进入 s_relay_pending */
+    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_SLOT_SELECT, (const uint8_t *)&fil_req, sizeof(fil_req));
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_TX node=TH seq=101 cmd=0x19 status=EXEC") != NULL);
+    /* 2. 在 seq=101 未收到 TH 响应前，尝试发起第2条级联 (seq=102, cmd=0x1C) 与本地 G-code 转发 */
+    minimc_gcode_req_t g_req = { 2U, 1U, "T2" };
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GCODE_EXEC, (const uint8_t *)&g_req, 4U);
+    assert(minimc_proto_send_th_gcode("M104 S200\r\n", 11U, 1U) == false);
+    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=102 cmd=0x1C status=TX_ERR err_code=0x06") != NULL);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_TX node=TH seq=102") == NULL);
+    /* 3. 验证注入伪造的 seq=102 响应被拒绝 (BAD_FRAME 0x07)，原 seq=101 关联状态完好无损 */
+    const minimc_gcode_resp_t th_g_resp = { 0U, 3U, 102U };
+    inject_th_custom_frame(MINIMC_CMD_GCODE_EXEC, 102U, (const uint8_t *)&th_g_resp, sizeof(th_g_resp));
+    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=102 cmd=0x1C status=BAD_FRAME err_code=0x07") != NULL);
+    /* 4. 注入匹配第1条 seq=101 的合法 0x19 TH 响应，正常完成同步并解除 pending */
+    const minimc_filament_resp_t th_fil_resp = { 1U, 0x0FU, 4U, 0U };
+    clear_usart1_capture();
+    inject_th_custom_frame(MINIMC_CMD_SLOT_SELECT, 101U, (const uint8_t *)&th_fil_resp, sizeof(th_fil_resp));
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=101 cmd=0x19 status=ACK") != NULL);
+    assert(strstr(s_usart1_tx_capture, "active_slot=1 filament_present_mask=0x0F step_state=DONE") != NULL);
+    /* 5. 解除 pending 后再次发起新级联 (seq=103, cmd=0x1C) 并收到 TH 响应，验证恢复成功 */
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GCODE_EXEC, (const uint8_t *)&g_req, 4U);
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_TX node=TH seq=103 cmd=0x1C status=EXEC") != NULL);
+    inject_th_custom_frame(MINIMC_CMD_GCODE_EXEC, 103U, (const uint8_t *)&th_g_resp, sizeof(th_g_resp));
+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=103 cmd=0x1C status=ACK") != NULL);
+}
