/**
 * @brief 由 MC 向 TH 发起级联控制帧 (0x10/0x19/0x1C) 并登记 RELAY_TX 状态
 * @param cmd_id 级联控制命令码
 * @param seq 16位序列号
 * @param payload 载荷数据指针
 * @param plen 载荷长度
 */
static void trigger_mc_to_th_cascade(uint8_t cmd_id, uint16_t seq, const void *payload, uint16_t plen)
{
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    if ((plen > MINIMC_MAX_PAYLOAD_SIZE) || s_relay_pending)
    {
        mc_dbg_log_tx_err("TH", seq_u8, cmd_id);
        return;
    }
    uint8_t frame[MINIMC_MAX_FRAME_SIZE];
    frame[0] = MINIMC_SOF_1;
    frame[1] = MINIMC_SOF_2;
    frame[2] = MINIMC_NODE_MC;
    frame[3] = MINIMC_NODE_TH;
    frame[4] = (uint8_t)(MINIMC_FLAG_WANTS_ACK | MINIMC_FLAG_PROTO_V2);
    frame[5] = cmd_id;
    frame[6] = MINIMC_DEFAULT_HOP_LIMIT;
    frame[7] = MINIMC_DEFAULT_ROUTE;
    frame[8] = seq_u8;
    frame[9] = (uint8_t)((seq >> 8U) & 0xFFU);
    frame[10] = (uint8_t)(plen & 0xFFU);
    frame[11] = (uint8_t)((plen >> 8U) & 0xFFU);
    if ((plen > 0U) && (payload != NULL))
    {
        (void)memcpy(frame + MINIMC_HEADER_SIZE, payload, plen);
    }
    const uint16_t body_len = (uint16_t)(MINIMC_HEADER_SIZE + plen);
    const uint16_t crc = minimc_crc16(frame, body_len);
    frame[body_len] = (uint8_t)(crc & 0xFFU);
    frame[body_len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);
    if (!forward_uart_send_raw(frame, (uint16_t)(body_len + MINIMC_CRC_SIZE)))
    {
        return;
    }
    s_relay_pending = true;
    s_relay_from_mc_local = true;
    s_relay_seq = seq_u8;
    s_relay_seq16 = seq;
    s_relay_cmd = cmd_id;
    s_relay_start_ms = wk_timebase_get();
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq_u8, cmd_id, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
}
    if (handle_mc_core_queries(cmd_id, seq, frame, resp))
    {
        return;
    }
    if (handle_mc_motion_and_level(cmd_id, seq, frame, resp))
    {
        return;
    }
    if (handle_mc_control_cmds(cmd_id, seq, frame))
    {
        return;
    }
    send_mc_nack(frame, seq, 0x04U);
}

/**
 * @brief 处理 AP 发往 TH (dst=0x03) 的级联转发请求帧，严格保护在途关联状态不被覆盖
 * @param frame 完整请求帧指针
 * @param len 帧总长度
 */
static void handle_th_relay_req(const uint8_t *frame, uint16_t len)
{
    const uint8_t cmd_id = frame[5];
    const uint8_t seq_u8 = frame[8];
    if (frame[6] <= 1U)
    {
        mc_dbg_log_frame_err(frame, "BAD_FRAME", 0x05U);
        return;
    }
    if (s_relay_pending)
    {
        mc_dbg_log_tx_err("TH", seq_u8, cmd_id);
        return;
    }
    uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
    relay_frame(frame, len, relay_buf);
    if (!forward_uart_send_raw(relay_buf, len))
    {
        mc_dbg_log_tx_err("TH", seq_u8, cmd_id);
        return;
    }
    s_relay_pending = true;
    s_relay_from_mc_local = false;
    s_relay_seq = seq_u8;
    s_relay_seq16 = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    s_relay_cmd = cmd_id;
    s_relay_start_ms = wk_timebase_get();
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq_u8, cmd_id, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
}

static void handle_ap_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    const uint8_t dst_id = frame[3];
    const uint8_t cmd_id = frame[5];
    const uint8_t seq_u8 = frame[8];
    char rx_kv[48];
    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u", (unsigned int)len);
    const mc_dbg_meta_t rx_meta = { "RX", mc_dbg_node_name(dst_id), seq_u8, cmd_id, "OK" };
    mc_dbg_emit(&rx_meta, rx_kv);

    if ((dst_id == MINIMC_NODE_MC) || (dst_id == 0xFFU))
    {
        handle_mc_query(frame, len);
        return;
    }
    if (dst_id == MINIMC_NODE_TH)
    {
        handle_th_relay_req(frame, len);
    }
}

static bool is_valid_th_relay_cmd(uint8_t req_cmd, uint8_t resp_cmd, uint16_t plen)
{
    if (resp_cmd == MINIMC_CMD_NACK)
    {
        return (plen >= 1U);
    }
    if (req_cmd == MINIMC_CMD_GET_VERSION)
    {
        return (resp_cmd == MINIMC_CMD_VERSION_REPORT);
    }
    }
    else if (step_id == 2U)
    {
        step_str = "LOADING";
    }
    else if (step_id == 3U)
    {
        step_str = "UNLOADING";
    }
    else if (step_id == 5U)
    {
        step_str = "FAULT";
    }
    active_extruder = active_slot;
    s_dbg_state.ack_seq = seq_u8;
    mc_debug_notify_filament("SELECT", active_slot, present_mask, step_str);
}

static void handle_th_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    uint8_t err_code = 0x07U;
    if (!validate_th_relay_resp(frame, &err_code))
    {
        char err_kv[32];
        (void)snprintf(err_kv, sizeof(err_kv), "err_code=0x%02X", (unsigned int)err_code);
        const mc_dbg_meta_t err_meta = { "ERR", "TH", frame[8], frame[5], "BAD_FRAME" };
        mc_dbg_emit(&err_meta, err_kv);
        return;
    }
    const uint8_t cmd_id = frame[5];
    const uint8_t seq_u8 = frame[8];
    const uint32_t elapsed = (uint32_t)(wk_timebase_get() - s_relay_start_ms);
    const bool was_mc_local = s_relay_from_mc_local;
    s_relay_pending = false;
    s_relay_from_mc_local = false;

    sync_th_temp_and_gcode_state(frame, seq_u8);
    sync_th_filament_resp_state(frame, seq_u8);

    char kv[64];
    const char *st = (cmd_id == MINIMC_CMD_NACK) ? "NACK" : "ACK";
    if (cmd_id == MINIMC_CMD_NACK)
    {
        (void)snprintf(kv, sizeof(kv), "err_code=0x%02X elapsed_ms=%lu", (unsigned int)frame[12], (unsigned long)elapsed);
    }
    else
    {
        (void)snprintf(kv, sizeof(kv), "elapsed_ms=%lu", (unsigned long)elapsed);
    }
    const mc_dbg_meta_t rrx_meta = { "RELAY_RX", "TH", seq_u8, cmd_id, st };
    mc_dbg_emit(&rrx_meta, kv);

    if ((!was_mc_local) && (frame[3] == MINIMC_NODE_AP))
    {
        uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
        relay_frame(frame, len, relay_buf);
        const bool tx_ok = minimc_proto_send(relay_buf, len);
        const mc_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, st };
        mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
    }
}

