static bool is_valid_th_relay_cmd(uint8_t req_cmd, uint8_t resp_cmd, uint16_t plen)
{
    if (resp_cmd == MINIMC_CMD_NACK)
    {
        return (plen >= 1U);
    }
    if (req_cmd == MINIMC_CMD_GET_VERSION)
    {
        return (resp_cmd == MINIMC_CMD_VERSION_REPORT);
    }
    if (req_cmd == MINIMC_CMD_PING)
    {
        return (resp_cmd == MINIMC_CMD_PONG);
    }
    if ((req_cmd == MINIMC_CMD_GET_TEMP) || (req_cmd == MINIMC_CMD_SET_TEMP))
    {
        return (resp_cmd == MINIMC_CMD_TEMP_REPORT) || (resp_cmd == 0x14U);
    }
    if ((req_cmd == MINIMC_CMD_FILAMENT_CONTROL) ||
        (req_cmd == MINIMC_CMD_SLOT_SELECT) ||
        (req_cmd == MINIMC_CMD_FILAMENT_LEGACY))
    {
        return (resp_cmd == MINIMC_CMD_SLOT_SELECT);
    }
    if (req_cmd == MINIMC_CMD_MOTION_STOP)
    {
        return (resp_cmd == MINIMC_CMD_ACK);
    }
    if (req_cmd == MINIMC_CMD_GCODE_EXEC)
    {
        return (resp_cmd == MINIMC_CMD_GCODE_EXEC);
    }
    return (resp_cmd == req_cmd);
}

static bool validate_th_relay_resp(const uint8_t *frame, uint8_t *out_err_code)
{
    if ((frame == NULL) || (out_err_code == NULL))
    {
        return false;
    }
    if (!s_relay_pending)
    {
        *out_err_code = 0x07U;
        return false;
    }
    const bool valid_dst = (frame[3] == MINIMC_NODE_AP) || (frame[3] == MINIMC_NODE_MC);
    if ((frame[2] != MINIMC_NODE_TH) || (!valid_dst) ||
        ((frame[4] & MINIMC_FLAG_IS_RESPONSE) == 0U))
    {
        *out_err_code = 0x07U;
        return false;
    }
    const uint16_t rx_seq16 = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
    if ((rx_seq16 != s_relay_seq16) || (!is_valid_th_relay_cmd(s_relay_cmd, frame[5], plen)))
    {
        *out_err_code = 0x07U;
        return false;
    }
    if (frame[6] <= 1U)
    {
        *out_err_code = 0x05U;
        return false;
    }
    *out_err_code = 0x00U;
    return true;
}

